const HIS_GROUPS = ["Niño", "Salud mental", "Vacunas", "Promoción y comunitarias", "Salud bucal", "Adulto mayor", "Adulto", "Pueblos indígenas", "Planificación familiar", "Salud ocular", "ITS y hepatitis", "Tuberculosis", "Cáncer", "Discapacidad", "Adolescente"];
const HIS_NINO_SRC = "Manual de Registro y Codificación — Etapa de Vida Niño, MINSA, febrero 2021";

function hisEsc(s) {
  return String(s == null ? "" : s).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}
function hisNorm(s) {
  return String(s || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
}
